import{_ as d,C as n,o as e,c as s,a2 as o,b as l,w as r,a as i,E as c,a3 as B}from"./chunks/framework.DSoq407f.js";const P=JSON.parse('{"title":"XUBP 协议概览","description":"","frontmatter":{},"headers":[],"relativePath":"xubp/overview.md","filePath":"xubp/overview.md","lastUpdated":1786505997000}'),g={name:"xubp/overview.md"};function p(h,t,E,_,u,b){const a=n("Mermaid");return e(),s("div",null,[t[1]||(t[1]=o('<h1 id="xubp-协议概览" tabindex="-1">XUBP 协议概览 <a class="header-anchor" href="#xubp-协议概览" aria-label="Permalink to &quot;XUBP 协议概览&quot;">​</a></h1><blockquote><p><strong>XUBP</strong> = <strong>X</strong>iaoyi <strong>U</strong>niversal <strong>B</strong>ot <strong>P</strong>rotocol（小依通用机器人协议）</p></blockquote><h2 id="什么是-xubp" tabindex="-1">什么是 XUBP <a class="header-anchor" href="#什么是-xubp" aria-label="Permalink to &quot;什么是 XUBP&quot;">​</a></h2><p>XUBP 是 V3 平台的<strong>通用插件开发协议</strong>。它定义了一套<strong>与平台无关的标准接口</strong>，让你只需编写一次插件代码，就能在所有已接入平台上运行——QQ 官方、OneBot、Telegram、Discord、KOOK、飞书、钉钉、微信公众号、企业微信。</p>',4)),(e(),l(B,null,{default:r(()=>[c(a,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20%E4%BD%A0%E7%9A%84%E6%8F%92%E4%BB%B6%5B%22%E4%BD%A0%E7%9A%84%E6%8F%92%E4%BB%B6%EF%BC%88%E5%90%8C%E4%B8%80%E4%BB%BD%E4%BB%A3%E7%A0%81%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20Code%5B%22handle_event%3Cbr%2F%3Econtext.reply()%22%5D%0A%20%20%20%20end%0A%20%20%20%20Code%20-.%E7%BB%9F%E4%B8%80%E6%8E%A5%E5%8F%A3.-%3E%20XUBP%5B%22XUBP%20%E6%A0%87%E5%87%86%E5%B1%82%22%5D%0A%20%20%20%20XUBP%20--%3E%20QQ%5B%22QQ%20%E5%AE%98%E6%96%B9%22%5D%0A%20%20%20%20XUBP%20--%3E%20TG%5B%22Telegram%22%5D%0A%20%20%20%20XUBP%20--%3E%20DC%5B%22Discord%22%5D%0A%20%20%20%20XUBP%20--%3E%20OB%5B%22OneBot%22%5D%0A%20%20%20%20XUBP%20--%3E%20More%5B%22...%E5%85%B6%E4%BB%96%205%20%E4%B8%AA%E5%B9%B3%E5%8F%B0%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<h2 id="核心思想-一次编写-多平台运行" tabindex="-1">核心思想：一次编写，多平台运行 <a class="header-anchor" href="#核心思想-一次编写-多平台运行" aria-label="Permalink to &quot;核心思想：一次编写，多平台运行&quot;">​</a></h2><p>不同平台的差异巨大——QQ 用 OpenID、OneBot 用 QQ 号、Telegram 用数字 chat_id、Discord 用 channel_id。如果插件要直接对接每个平台，代码里会塞满 <code>if 平台 == qq: ... else if 平台 == telegram: ...</code>。</p><p>XUBP 的做法是<strong>把差异吸收进适配器</strong>：</p><ul><li><strong>统一事件格式</strong>：所有平台的事件，经适配器标准化后，插件看到的都是同一种结构。</li><li><strong>统一回复方法</strong>：<code>context.reply(&quot;你好&quot;)</code> 一行代码，自动适配每个平台的发送方式。</li><li><strong>统一字段</strong>：<code>context.sender_id</code>、<code>context.chat_id</code> 等属性，跨平台通用，插件不用关心底层 ID 是什么格式。</li></ul><div class="tip custom-block"><p class="custom-block-title">插件开发者的心智模型</p><p>写插件时，<strong>假装只有一个平台</strong>。用 <code>context.reply()</code> 回复、用 <code>context.sender_id</code> 取用户、用 <code>context.chat_id</code> 取聊天空间。至于这条回复最终发到 QQ 还是 Telegram，由适配器处理，与你无关。</p></div><h2 id="xubp-提供了什么" tabindex="-1">XUBP 提供了什么 <a class="header-anchor" href="#xubp-提供了什么" aria-label="Permalink to &quot;XUBP 提供了什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td><strong>统一事件类型</strong></td><td>17 种通用事件类型（消息、机器人状态、交互、表态、审核），点分命名如 <code>message.group</code></td></tr><tr><td><strong>统一事件结构</strong></td><td>标准化的 event 字典，包含发送者、会话、内容、附件等</td></tr><tr><td><strong>统一消息格式</strong></td><td><code>send_message</code> 的 payload 格式，支持文本、富媒体、Markdown、按钮等</td></tr><tr><td><strong>统一上下文</strong></td><td>Context 对象提供跨平台属性和回复方法</td></tr><tr><td><strong>数据存储</strong></td><td><code>data_store</code> 接口，按租户自动隔离</td></tr><tr><td><strong>拦截器</strong></td><td>可在消息发出前/后介入，实现内容过滤、审计等</td></tr></tbody></table><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><ol><li>先看 <a href="./events">事件类型</a>——了解插件能响应哪些事。</li><li>看 <a href="./message-flow">消息流转</a>——理解一条消息如何从平台到达你的插件。</li><li>进入 <a href="./../plugin-dev/getting-started">插件开发</a>——动手写第一个插件。</li></ol><h2 id="这份协议面向谁" tabindex="-1">这份协议面向谁 <a class="header-anchor" href="#这份协议面向谁" aria-label="Permalink to &quot;这份协议面向谁&quot;">​</a></h2><p>XUBP 是<strong>插件开发者</strong>的协议。如果你想<strong>新增一个平台适配器</strong>（让 V3 支持一个全新的 IM 平台），那是平台内部能力，不包含在本公开协议内——请联系平台方。</p>',11))])}const x=d(g,[["render",p]]);export{P as __pageData,x as default};
